153→<script>
154→let ws, username='';
155→document.getElementById('name-input').addEventListener('keydown', e=>{ if(e.key==='Enter') joinChat(); });
156→
157→function joinChat(){
158→    username = document.getElementById('name-input').value.trim();
159→    if(!username){ alert('请输入昵称！'); return; }
160→    document.getElementById('login-panel').style.display='none';
161→    document.getElementById('chat-panel').style.display='flex';
162→    const host = location.hostname || 'localhost';
163→    ws = new WebSocket('ws://'+host+':8765');
164→    ws.onopen = ()=>{
165→        document.getElementById('status-text').textContent='✅ 已连接';
166→        ws.send(JSON.stringify({name:username}));
167→        document.getElementById('msg-input').focus();
168→    };
169→    ws.onmessage = (e)=> addMessage(JSON.parse(e.data));
170→    ws.onclose = ()=>{
171→        document.getElementById('status-text').textContent='❌ 已断开';
172→        addMessage({type:'system',message:'连接已断开，请刷新页面重试',time:''});
173→    };
174→}
175→
176→function addMessage(d){
177→    const div=document.createElement('div'); div.classList.add('msg');
178→    if(d.type==='system'){ div.classList.add('msg-system'); div.textContent=d.time+' '+d.message; }
179→    else if(d.type==='chat'){
180→        div.classList.add(d.from===username?'msg-self':'msg-chat');
181→        div.innerHTML='<div class="name">'+d.time+' '+d.from+'</div><div>'+esc(d.message)+'</div>';
182→    } else if(d.type==='private'){
183→        div.classList.add('msg-chat','msg-private');
184→        div.innerHTML='<div class="name">🔒 '+d.time+' '+d.from+' (私聊)</div><div>'+esc(d.message)+'</div>';
185→    } else if(d.type==='private_echo'){
186→        div.classList.add('msg-self','msg-private-echo');
187→        div.innerHTML='<div class="name">🔒 '+d.time+' → '+d.to+' (私聊)</div><div>'+esc(d.message)+'</div>';
188→    }
189→    const m=document.getElementById('messages'); m.appendChild(div); m.scrollTop=m.scrollHeight;
190→}
191→
192→function sendMsg(){
193→    const i=document.getElementById('msg-input'), msg=i.value.trim();
194→    if(!msg||!ws||ws.readyState!==WebSocket.OPEN) return;
195→    ws.send(JSON.stringify({message:msg})); i.value=''; i.focus();
196→}
197→function esc(t){ const d=document.createElement('div'); d.textContent=t; return d.innerHTML; }
198→</script>
