170→.typing-indicator span:nth-child(3) { animation-delay: 0.4s; }
171→@keyframes typingDot { 0%,60%,100%{opacity:0.3;transform:translateY(0)} 30%{opacity:1;transform:translateY(-4px)} }
172→
173→/* === Notification toast === */
174→.toast {
175→    position: fixed; top: 20px; right: 20px; z-index: 999;
176→    background: rgba(22,33,62,0.9); backdrop-filter: blur(15px);
177→    border: 1px solid rgba(255,255,255,0.1); border-radius: 12px;
178→    padding: 12px 20px; color: #e6e6e6; font-size: 13px;
179→    box-shadow: 0 8px 30px rgba(0,0,0,0.3);
180→    animation: toastIn 0.4s ease-out, toastOut 0.4s ease-in 3s forwards;
181→    display: flex; align-items: center; gap: 8px;
182→}
183→@keyframes toastIn { from{opacity:0;transform:translateX(40px)} to{opacity:1;transform:translateX(0)} }
184→@keyframes toastOut { from{opacity:1} to{opacity:0;transform:translateX(40px)} }
185→
186→/* === Connection lost overlay === */
