208→<body>
209→<!-- Floating background orbs -->
210→<div class="orb orb-1"></div>
211→<div class="orb orb-2"></div>
212→<div class="orb orb-3"></div>
213→
214→<div id="login-panel">
215→    <div class="logo">💬</div>
216→    <h1>欢迎来到 <span>聊天室</span></h1>
217→    <p>输入你的昵称，开始聊天吧 ✨</p>
218→    <input id="name-input" type="text" placeholder="输入你的昵称..." maxlength="20" autofocus />
219→    <button onclick="joinChat()">🚀 加入聊天</button>
220→    <div class="hint">提示：输入 <code>@用户名 消息</code> 可以发送私聊</div>
221→</div>
222→
223→<div id="chat-panel">
224→    <div id="chat-header">
225→        <h2>💬 聊天室</h2>
226→        <div style="display:flex;align-items:center;gap:12px;">
227→            <span id="online-badge">在线</span>
228→            <span id="status-text">连接中...</span>
229→        </div>
230→    </div>
231→    <div id="messages"></div>
232→    <div class="typing-indicator" id="typing-indicator">
233→        <span></span><span></span><span></span>
234→    </div>
235→    <div id="input-area">
236→        <input id="msg-input" type="text" placeholder="输入消息... (用 @用户名 私聊)" onkeydown="if(event.key==='Enter')sendMsg()" />
237→        <button onclick="sendMsg()">发送 ✈️</button>
238→    </div>
239→    <div class="reconnect-overlay" id="reconnect-overlay">
240→        <div class="spinner"></div>
241→        <div>连接已断开，正在尝试重连...</div>
242→    </div>
243→</div>
244→
245→<script>
246→let ws, username='', reconnectTimer=null, onlineCount=0;
247→
248→document.getElementById('name-input').addEventListener('keydown', e=>{ if(e.key==='Enter') joinChat(); });
249→
250→function showToast(msg, icon='ℹ️') {
251→    const t = document.createElement('div');
252→    t.className = 'toast';
253→    t.innerHTML = '<span>' + icon + '</span><span>' + esc(msg) + '</span>';
254→    document.body.appendChild(t);
255→    setTimeout(() => t.remove(), 3600);
256→}
257→
258→function joinChat(){
259→    username = document.getElementById('name-input').value.trim();
260→    if(!username){ alert('请输入昵称！'); return; }
261→    document.getElementById('login-panel').style.display='none';
262→    document.getElementById('chat-panel').style.display='flex';
263→    connectWS();
264→}
265→
266→function connectWS() {
267→    if (reconnectTimer) { clearTimeout(reconnectTimer); reconnectTimer = null; }
268→    document.getElementById('reconnect-overlay').classList.remove('show');
269→    document.getElementById('status-text').textContent='连接中...';
270→
271→    const host = location.hostname || 'localhost';
272→    ws = new WebSocket('ws://'+host+':8765');
273→    ws.onopen = ()=>{
274→        document.getElementById('status-text').textContent='✅ 已连接';
275→        document.getElementById('reconnect-overlay').classList.remove('show');
276→        ws.send(JSON.stringify({name:username}));
277→        document.getElementById('msg-input').focus();
278→        showToast('已连接到聊天服务器', '🟢');
279→    };
280→    ws.onmessage = (e)=>{
281→        const d = JSON.parse(e.data);
282→        // Track online count from server broadcasts
283→        if (d.type === 'online_count') {
284→            onlineCount = d.count;
285→            document.getElementById('online-badge').textContent = onlineCount + ' 在线';
286→            return;
287→        }
288→        addMessage(d);
289→    };
290→    ws.onclose = ()=>{
291→        document.getElementById('status-text').textContent='❌ 已断开';
292→        document.getElementById('reconnect-overlay').classList.add('show');
293→        // Auto reconnect after 3 seconds
294→        reconnectTimer = setTimeout(() => {
295→            addMessage({type:'system',message:'正在尝试重新连接...',time:''});
296→            connectWS();
297→        }, 3000);
298→    };
299→    ws.onerror = ()=>{};
300→}
301→
302→function addMessage(d){
303→    const div=document.createElement('div'); div.classList.add('msg');
304→    if(d.type==='system'){
305→        div.classList.add('msg-system');
306→        div.textContent=(d.time?d.time+' ':'')+d.message;
307→    } else if(d.type==='chat'){
308→        div.classList.add(d.from===username?'msg-self':'msg-chat');
309→        div.innerHTML='<div class="name">'+esc(d.time)+' '+esc(d.from)+'</div><div>'+esc(d.message)+'</div>';
310→        if(d.from!==username) showNotif(d.from, d.message);
311→    } else if(d.type==='private'){
312→        div.classList.add('msg-chat','msg-private');
313→        div.innerHTML='<div class="name">🔒 '+esc(d.time)+' '+esc(d.from)+' (私聊)</div><div>'+esc(d.message)+'</div>';
314→        showNotif(d.from, '🔒 私聊: ' + d.message);
315→    } else if(d.type==='private_echo'){
316→        div.classList.add('msg-self','msg-private-echo');
317→        div.innerHTML='<div class="name">🔒 '+esc(d.time)+' → '+esc(d.to)+' (私聊)</div><div>'+esc(d.message)+'</div>';
318→    }
319→    const m=document.getElementById('messages'); m.appendChild(div); m.scrollTop=m.scrollHeight;
320→}
321→
322→function sendMsg(){
323→    const i=document.getElementById('msg-input'), msg=i.value.trim();
324→    if(!msg||!ws||ws.readyState!==WebSocket.OPEN) return;
325→    ws.send(JSON.stringify({message:msg})); i.value=''; i.focus();
326→}
327→
328→function esc(t){ const d=document.createElement('div'); d.textContent=t; return d.innerHTML; }
329→
330→// Browser notification (if permitted)
331→function showNotif(from, msg) {
332→    if (Notification.permission === 'granted') {
333→        new Notification(from + ' 说:', { body: msg, icon: '💬' });
334→    }
335→}
336→
337→// Request notification permission on load
338→if ('Notification' in window && Notification.permission === 'default') {
339→    Notification.requestPermission();
340→}
341→
342→// Reconnect button handler for status text click
343→document.getElementById('status-text').style.cursor = 'pointer';
344→document.getElementById('status-text').addEventListener('click', () => {
345→    if (ws && ws.readyState !== WebSocket.OPEN) connectWS();
346→});
347→</script>
